<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/chat.php';$u=require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']);$f=db_one('SELECT f.*,n.ma_hoi_thoai FROM tep_tin_nhan f JOIN tin_nhan n ON n.ma_tin_nhan=f.ma_tin_nhan WHERE f.id=?',[get('id')]);must((bool)$f,'Tệp không tồn tại.',404);conversation((int)$f['ma_hoi_thoai'],$u);must((bool)preg_match('~^attachments/[a-f0-9]{32}\.(jpg|png|webp|pdf)$~D',$f['duong_dan']),'Đường dẫn tệp không hợp lệ.');$path=PRIVATE_DIR.'/'.$f['duong_dan'];must(is_file($path),'Tệp không còn trên máy chủ.',404);session_write_close();header('Content-Type: '.$f['mime']);header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($f['ten_goc']));header('Content-Length: '.filesize($path));readfile($path);exit;
